package main

const editionHTML = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>__EDITION__</title><style>
:root{color-scheme:dark;--bg:#10141b;--panel:#181f2a;--line:#2b3545;--text:#eaf0f8;--muted:#98a6bb;--gold:#e8bf70;--accent:#74d6ca}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.6 "Microsoft YaHei",sans-serif}header{padding:23px 32px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center}h1{margin:0;font-size:24px}h1 span{color:var(--gold)}.tag{border:1px solid #52604a;background:#222a22;color:var(--gold);padding:6px 14px;border-radius:20px}main{display:grid;grid-template-columns:280px 1fr;gap:24px;padding:24px;max-width:1450px;margin:auto}.card{background:var(--panel);border:1px solid var(--line);border-radius:13px;padding:20px;margin-bottom:18px}h2{font-size:17px;margin:0 0 14px}.muted{color:var(--muted);font-size:12px}.banner{border-left:3px solid var(--gold);padding:14px;background:#25251f;border-radius:7px;margin-bottom:18px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.row{display:flex;gap:10px}.row>*{flex:1}label{display:block;color:var(--muted);font-size:12px;margin:10px 0 5px}input,select{width:100%;background:#101720;color:var(--text);border:1px solid #344156;padding:10px;border-radius:6px;font:inherit}input:focus,select:focus{outline:1px solid var(--gold)}button{background:var(--gold);color:#161b23;border:0;border-radius:6px;padding:10px 17px;font:inherit;font-weight:600;cursor:pointer}button.secondary{background:#29374a;color:var(--text)}button:disabled{opacity:.45;cursor:wait}button.small{padding:5px 10px;font-size:12px}table{width:100%;border-collapse:collapse;font-size:12px}td,th{padding:9px 7px;border-bottom:1px solid var(--line);text-align:left}th{color:var(--muted)}.scroll{max-height:340px;overflow:auto}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#0f151e;border-radius:7px;padding:14px;font-size:12px;max-height:340px;overflow:auto}#target{font-size:17px;color:var(--accent);margin:10px 0}#message{padding:12px 16px;border-radius:7px;background:#202c3b;margin-bottom:18px;min-height:46px;overflow-wrap:anywhere}#connection{max-width:480px;text-align:right;color:var(--muted);font-size:12px}aside .muted{overflow-wrap:anywhere}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:14px}@media(max-width:1000px){main{grid-template-columns:1fr}.grid{grid-template-columns:1fr}header{padding:18px}.tag{display:none}}
</style></head><body><header><div><h1>__EDITION__</h1><div class="muted">角色管理 / 原生物品目录 / 审计与备份</div></div><div id="connection">正在连接本机管理服务…</div><div class="tag">服主专用 · 1.0.0</div></header><main><aside><div class="card"><h2>管理目标</h2><label>账号</label><select id="account"></select><label>角色</label><select id="role"></select><div id="target">请选择角色</div><div id="balances" class="muted"></div><div class="actions"><button id="refresh" class="secondary">刷新资料</button></div></div><div class="card"><h2>存档位置</h2><div id="database" class="muted"></div><p class="muted">单机版只管理本机存档。联网版在云服务器桌面运行，只管理云服存档。</p><p class="muted">修改前停止对应服务端。GM不会自动停服、踢人或启动游戏。</p></div></aside><section><div class="banner" id="note">正在准备管理信息…</div><div id="message">首次加载原生物品目录需要等待。请保留GM程序窗口。</div><div class="grid"><div class="card"><h2>金币与点券</h2><div class="row"><div><label>增加金币</label><input id="gold" type="number" min="0" max="4294967295" value="0"></div><div><label>点券调整（负数为扣除）</label><input id="cera" type="number" value="0"></div></div><label>操作原因（记录到审计）</label><input id="currencyReason" placeholder="例如：测试奖励"><div class="actions"><button id="grantCurrency">确认发放</button></div></div><div class="card"><h2>角色等级</h2><label>目标等级（PVF原生范围）</label><input id="level" type="number" min="2" value="115"><label>操作原因</label><input id="levelReason" placeholder="例如：等级测试"><div class="actions"><button id="setLevel">调整等级</button></div><p class="muted">同步等级与累计经验；不自动赠送技能点、转职觉醒或任务进度。</p></div></div><div class="card"><h2>物品与装备发放</h2><div class="row"><input id="query" placeholder="输入物品名字或编号"><button id="search" class="secondary" style="flex:0 0 auto">搜索物品</button></div><div class="scroll"><table><thead><tr><th>编号</th><th>名字</th><th>类别 / 品级</th><th>选择</th></tr></thead><tbody id="items"></tbody></table></div><div class="row"><div><label>物品编号</label><input id="template" type="number" min="1"></div><div><label>数量</label><input id="amount" type="number" min="1" value="1"></div><div><label>发放原因</label><input id="itemReason" placeholder="例如：装备测试"></div></div><div class="actions"><button id="grantItem">发放到角色背包</button></div><p class="muted">只允许当前PVF内存在的物品；背包容量、物品属性与堆叠限制交给服务端校验。</p></div><div class="grid"><div class="card"><h2>备份与操作记录</h2><p class="muted">每次修改前先备份整库，包含WAL中已提交的数据；备份失败则取消修改。备份保留在对应存档的 gm-backups 目录。</p><div class="actions"><button id="backup">立即备份</button><button id="history" class="secondary">账号操作记录</button><button id="backups" class="secondary">备份列表</button></div><pre id="output">尚未执行操作</pre></div><div class="card"><h2>当前角色背包</h2><div class="scroll"><table><thead><tr><th>位置</th><th>物品</th><th>数量</th></tr></thead><tbody id="bag"></tbody></table></div></div></div></section></main><script>
'use strict';
const token=location.hash.slice(1)||sessionStorage.getItem('gm-token');if(token){sessionStorage.setItem('gm-token',token);history.replaceState(null,'',location.pathname)}
const $=id=>document.getElementById(id);let account=0,role=0,status={},busy=false;const pending=new Map();
function message(text,error=false){$('message').textContent=text;$('message').style.color=error?'#ffaaaa':'#b3eadb'}
async function api(path,body){const r=await fetch(path,{method:body===undefined?'GET':'POST',headers:{'X-GM-Token':token,'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),cache:'no-store'});let data;try{data=await r.json()}catch{throw Error('管理服务无响应，请检查GM程序窗口')}if(!r.ok||data.error)throw Error(data.error||('请求失败 '+r.status));return data}
async function run(fn){if(busy)return;busy=true;document.querySelectorAll('button,select').forEach(b=>b.disabled=true);try{await fn()}catch(e){message(e.message,true)}finally{busy=false;document.querySelectorAll('button,select').forEach(b=>b.disabled=b.dataset.unavailable==='true')}}
function option(parent,value,text){const el=document.createElement('option');el.value=value;el.textContent=text;parent.append(el)}
function cells(parent,values){const tr=document.createElement('tr');for(const value of values){const td=document.createElement('td');td.textContent=value;tr.append(td)}parent.append(tr);return tr}
function integer(id,min=0,max=4294967295){const n=Number($(id).value);if(!Number.isSafeInteger(n)||n<min||n>max)throw Error('请检查 '+id+' 的数值范围');return n}
function requireRole(){if(!account||!role)throw Error('请先选择账号和角色')}
function reason(id){const r=$(id).value.trim();if(!r)throw Error('请填写操作原因');return r}
function newID(){const bytes=new Uint8Array(16);crypto.getRandomValues(bytes);return 'gm-'+Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('')}
async function mutate(path,body,description){requireRole();const st=await api('/api/gm/status');if(!st.write_ready)throw Error('服务端正在运行或存档租约未释放，请停止对应服务端后重试');if(!confirm('__EDITION__\n账号：'+$('account').selectedOptions[0].textContent+'\n角色：'+$('role').selectedOptions[0].textContent+'\n'+description+'\n修改前将自动备份，是否执行？'))return;const key=path+JSON.stringify(body);let id=pending.get(key);if(!id){id=newID();pending.set(key,id)}body.grant_id=id;const result=await api(path,body);pending.delete(key);$('output').textContent=JSON.stringify(result,null,2);message(result.applied===false?'该操作已执行过，已返回原始回执，未重复修改。':'操作成功，启动游戏后可查看结果。');await details()}
async function loadStatus(){status=await api('/api/gm/status');$('connection').textContent=status.label+' · 本机连接正常';$('database').textContent=status.database;$('note').textContent=status.note;$('level').max=Math.min(255,status.level_max)}
async function accounts(){await loadStatus();const d=await api('/api/overview');$('account').replaceChildren();option($('account'),0,'请选择账号');for(const a of d.accounts)option($('account'),a.id,a.username+' (#'+a.id+')');$('role').replaceChildren();option($('role'),0,'请选择角色');message('管理服务已就绪，请选择账号和角色。')}
async function roles(){account=Number($('account').value);role=0;$('role').replaceChildren();option($('role'),0,'请选择角色');$('target').textContent='请选择角色';$('balances').textContent='';$('bag').replaceChildren();if(!account)return;const d=await api('/api/characters?account='+account);for(const c of d.characters)option($('role'),c.id,c.name+' · Lv.'+c.level+' (#'+c.id+')');$('balances').textContent='账号点券：'+d.cera}
async function details(){role=Number($('role').value);if(!role)return;const d=await api('/api/character?id='+role);$('target').textContent=d.character.name+' · Lv.'+d.character.level;$('balances').textContent='金币：'+d.character.gold+' / 点券：'+d.cera;$('bag').replaceChildren();for(const b of d.bag||[])cells($('bag'),[(b.worn?'穿戴 ':'背包 ')+b.slot,b.name+' ['+b.template+']',b.count])}
$('account').onchange=()=>run(roles);$('role').onchange=()=>run(details);$('refresh').onclick=()=>run(async()=>{await loadStatus();await details();message('资料已刷新')});
$('search').onclick=()=>run(async()=>{const d=await api('/api/items?limit=60&q='+encodeURIComponent($('query').value));$('items').replaceChildren();for(const it of d.items||[]){const tr=cells($('items'),[it.id,it.name,(it.type_label||it.kind)+' / '+(it.rarity_label||it.rarity)]);const td=document.createElement('td'),b=document.createElement('button');b.textContent=it.grantable?'选择':'不可发放';b.className='small secondary';b.disabled=!it.grantable;b.dataset.unavailable=String(!it.grantable);b.onclick=()=>{$('template').value=it.id;message('已选择：'+it.name+' ('+it.id+')')};td.append(b);tr.append(td)}message('显示 '+d.count+' 个结果（最多60个，请缩小关键词）')});
$('query').onkeydown=e=>{if(e.key==='Enter')$('search').click()};
$('grantCurrency').onclick=()=>run(async()=>{const gold=integer('gold'),cera=integer('cera',-2147483648,2147483647);if(!gold&&!cera)throw Error('请填写非零的金币或点券数量');await mutate('/api/grant',{account,character:role,gold,cera,reason:reason('currencyReason')},'金币 +'+gold+'，点券调整 '+cera)});
$('grantItem').onclick=()=>run(async()=>{const template=integer('template',1),amount=integer('amount',1);await mutate('/api/grant',{account,character:role,items:[{template,amount}],reason:reason('itemReason')},'发放物品 '+template+' × '+amount)});
$('setLevel').onclick=()=>run(async()=>{const level=integer('level',2,Math.min(255,status.level_max));await mutate('/api/gm/level',{account,character:role,level,reason:reason('levelReason')},'将等级设为 '+level+'（不赠送技能点）')});
$('backup').onclick=()=>run(async()=>{const d=await api('/api/gm/backup',{});$('output').textContent=JSON.stringify(d.backup,null,2);message('一致性备份与SHA256校验完成')});
$('history').onclick=()=>run(async()=>{if(!account)throw Error('请先选择账号');$('output').textContent=JSON.stringify((await api('/api/history?account='+account)).history,null,2);message('已读取当前账号的操作记录')});
$('backups').onclick=()=>run(async()=>{$('output').textContent=JSON.stringify((await api('/api/gm/backups')).backups||[],null,2);message('已读取本版本的备份列表')});
if(!token)message('访问凭证缺失，请关闭此页面并重新启动GM程序。',true);else run(accounts);
</script></body></html>`
